return ['domain'=>'page-builder-sandwich','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'sw','project-id-version'=>'page-builder-sandwich','pot-creation-date'=>'2026-09-26T16:59:17+00:00','po-revision-date'=>'2026-09-26T16:59:17+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Page Builder Sandwich'=>'Page Builder Sandwich','https://zinndigital.com/wordpress-plugins/page-builder-sandwich'=>'https://zinndigital.com/wordpress-plugins/page-builder-sandwich','The foundation release of the rebuilt Page Builder Sandwich: a settings and About screen, a footprint-free front-end output layer, and one sample content block.'=>'Toleo la msingi la Page Builder Sandwich iliyojengwa upya: skrini ya mipangilio na Kuhusu, safu ya pato la mbele isiyo na alama za SEO, na kizuizi kimoja cha maudhui ya sampuli.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'Watoa huduma za AI','The makers of ChatGPT. A good all-rounder.'=>'Waundaji wa ChatGPT. Kifaa kizuri cha matumizi yote.','The makers of Claude. Strong at writing and careful reasoning.'=>'Watengenezaji wa Claude. Wana nguvu katika uandishi na hoja makini.','Google\'s Gemini models. Fast and inexpensive.'=>'Miundo ya Gemini ya Google. Haraka na ya gharama nafuu.','A European AI company with fast, inexpensive models.'=>'Kampuni ya Uropa ya AI yenye mifumo ya haraka na ya bei nafuu.','Low-cost models that are good at writing and code.'=>'Mifumo ya bei ya chini ambayo ni mizuri katika uandishi na msimbo.','One key for models from many different providers.'=>'Ufunguo mmoja kwa ajili ya mifモデル kutoka kwa watoa huduma mbalimbali.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Huduma yoyote inayofanya kazi kama API ya OpenAI, ikiwa ni pamoja na mtindo unaofanya kazi kwenye kompyuta au seva yako mwenyewe.','General (used when nothing more specific is set)'=>'Jumla (inatum。「tumika wakati hakuna maalum zaidi iliyowekwa」)','Writing and rewriting'=>'Kuandika na kuandika upya','Translation'=>'Tafsiri','Code and CSS'=>'Nambari ya siri na CSS','Sorry, you are not allowed to access this page.'=>'Samahani, huruhusiwi kufikia ukurasa huu.','These settings are shared by every plugin that uses them: %s.'=>'Mipangilio hii inashirikiwa na kila programu-jalizi inayozitumia: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Ufunguo wako umesimbwa kwa njia fiche katika hifadhidata ya tovuti hii na hutumwa tu kwa mtoa huduma uliyemchagua — kamwe hawatumwi kwetu.','Step 1 of 2: choose an AI provider'=>'Hatua ya 1 kati ya 2: chagua mtoa huduma wa AI','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Unaleta ufunguo wako mwenyewe, kwa hiyo unamlipa mtoa huduma moja kwa moja kwa kile unachotumia. Huwa na uhakika? Yoyote kati ya hizi inafanya kazi vizuri; unaweza kuongeza nyingine baadaye.','Next'=>'Ifanye Ifuatayo','Step 2 of 2: connect %s'=>'Hatua ya 2 kati ya 2: unganisha %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Weka anwani ya huduma yako inayooana na OpenAI, inayomalizika kwa /v1. Ufunguo unahitajika tu ikiwa huduma inaomba mmoja.','Open %s and sign in (or create a free account).'=>'Fungua %s na uingie (au ufungue akaunti ya bure).','the %s API keys page'=>'kurasa ya funguo za API za %s','Create a new key and copy it.'=>'Tengeneza ufunguo mpya kisha uunakili.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Bandika hapa chini kisha ubonyeze "Hifadhi na ujaribu". Tunatuma ombi moja dogo ili kuangalia kama inafanya kazi.','Most providers need a little credit on the account before a key works: %s.'=>'Watoa huduma wengi wanahitaji mkopo kidogo kwenye akaunti kabla ya ufunguo kufanya kazi: %s.','add credit'=>'ongeza mkopo','← Choose a different provider'=>'← Chagua mtoa huduma mwingine','Address'=>'Anwani','Saved key ends in …%s — paste a new one to replace it'=>'Ufunguo uliyohifadhi unaishia katika …%s — bandika mpya ili kuubadilisha','Key (optional)'=>'Ufunguo (si lazima)','API key'=>'Ufunguo wa API','Save and test'=>'Hifadhi na jaribu','Providers'=>'Watoaji huduma','Provider'=>'Mtoa Huduma','Status'=>'Hali','Key'=>'Ufunguo','Get a key'=>'Pata ufunguo','Test'=>'Jaribu','Remove'=>'Ondoa','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Imesohifadhiwa na toleo jipya zaidi la programu-jalizi: sasisha programu-jalizi hii, au uweke ufunguo tena.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Ufunguo uliookolewa hauwezi kufunguliwa tena (funguo za usalama za tovuti zilibadilika). Ingiza tena.','Not connected'=>'Haijaunganishwa','Connected — last test passed %s'=>'Imeunganishwa — jaribio la mwisho limefaulu %s','Last test failed: %s'=>'Jaribio la mwisho limeshindwa: %s','Connected — not tested yet'=>'Imeunganishwa — haijajaribiwa bado','Which model to use'=>'Mtindo gani wa kutumia','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ inaashiria pendekezo letu kwa kazi hiyo. Orodha hiyo inajumuisha kila modeli ambayo ufunguo wako unaweza kutumia, iliyosomwa moja kwa moja kutoka kwa mtoa huduma.','— Recommended for the provider —'=>'— Inapendekezwa kwa mtoa huduma —','Save models'=>'Hifadhi mifano','Refresh the model lists from the providers'=>'Onyesha upya orodha za mifni kutoka kwa watoa huduma','best quality'=>'ubora bora','lowest cost'=>'gharama ya chini kabisa','fastest'=>'ya kasi zaidi','Add a model yourself'=>'Ongeza modeli mwenyewe','A model came out today? Paste its exact name to use it straight away.'=>'Modeli imetoka leo? Bandika jina lake kamili ili uitumie mara moja.','Model name'=>'Jina la mfano','Add model'=>'Ongeza modeli','Recommended models list'=>'Orodha ya mifano inayopendekezwa','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Orodha ya miundo inayopendekezwa haikuweza kuthibitishwa, kwa hiyo hakuna mapendekezo yanayoonyeshwa. Sakinisha tena programu-jalizi, au uwashe masasisho ya kila siku hapa chini.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Orodha inayotumika ilichapishwa mnamo %s. Kila sasisho la programu-jalizi huleta mpya.','Also check Zinn Digital® once a day for an updated list.'=>'Pia angalia Zinn Digital® mara moja kwa siku kwa orodha iliyosasishwa.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Ombi la upakuaji wa kawaida tu ndilo linalotumwaje: hakuna ufunguo, hakuna anwani ya tovuti, hakuna chochote kuhusu maudhui yako. Orodha hiyo imetiwa saini, na orodha ambayo inashindwa ukaguzi wa sahihi hupuuzwa.','Last checked %1$s: %2$s.'=>'Ilichunguzwa mwisho %1$s: %2$s.','Save, and check now if turned on'=>'Hifadhi, na uangalie sasa ikiwa imewashwa','a newer list was installed'=>'orododha mpya zaidi imewekwa','already up to date'=>'imesasasishwa kabisa','the download failed the signature check and was ignored'=>'upakuaji umeshindwa ukaguzi wa sahihi na umepuuzwa','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® haikuwezi kufikiwa; orodha ya sasa inaendelea kutumika','turned off'=>'imezimwa','Open'=>'Fungua','Check their status page'=>'Angalia ukurasa wao wa hali','Open your billing page'=>'Fungua ukurasa wako wa malipo','Open your API keys page'=>'Fungua ukurasa wako wa funguo za API','Open the AI settings'=>'Fungua mipangilio ya AI','Sorry, you are not allowed to do that.'=>'Samahani, huruhusiwi kufanya hivyo.','Unknown provider.'=>'Mtoa huduma asiyejulikana.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Weka anwani ya huduma yako, kwa mfano http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Hiyo haionekani kama ufunguo wa API. Nakili tena, bila nafasi.','Paste your API key first.'=>'Bandika ufunguo wako wa API kwanza.','Key removed.'=>'Ufunguo umeondolewa.','Models saved.'=>'Modeli zimehifadhiwa.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Weka jina halisi la modeli, kwa mfano kama nyaraka za mtoa huduma zinavyoandika.','Added %s. Choose it under "Which model to use".'=>'%s imeongezwa. Ichague chini ya "Which model to use".','Model removed.'=>'Modeli imeondolewa.','Daily updates are off. The list that came with the plugin is used.'=>'Sasisho za kila siku zimezimwa. Orodha iliyokuja na programu-jalizi inatumika.','Checked: %s.'=>'Imetejwa: %s.','Model lists refreshed.'=>'Orodha za miundo zimesasishwa.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Ufunguo wako wa AI umehifadhiwa na toleo jipya zaidi la moja ya programu-jalizi zako. Sasisha programu-jalizi hii, au uweke ufunguo huo tena katika mipangilio ya AI.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Ufunguo wako wa AI uliohifadhiwa hauwezi tena kufunguliwa (funguo za usalama za tovuti zimebadilika). Weka upya katika mipangilio ya AI.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'AI bado haijasanidiwa. Ongeza ufunguo wa mtoa huduma wa AI katika mipangilio ya AI.','No model is chosen for this task. Pick one in the AI settings.'=>'Hakuna mfano ulioteuliwa kwa kazi hii. Chagua moja katika mipangilio ya AI.','That AI provider is not supported by this version of the plugin.'=>'Mtoa huduma huyo wa AI hautumiki na toleo hili la programu-jalizi.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Tovuti hii haikuweza kufikia huduma yako ya AI. Hakikisha kuwa inafanya kazi na kwamba anwani yake inaweza kufikiwa kutoka kwa seva yako ya mtandao (huduma iliyo kwenye kompyuta yako mwenyewe haiwezi kufikiwa kutoka kwa tovuti inayopangishwa).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Tovuti hii haikuweza kufikia %s. Angalia ukurasa wao wa hali; ikiwa iko hewani, mwenyeji wako anaweza kuwa anazuia miunganisho ya kutoa, au anwani si sahihi.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s inasema kuwa akaunti yako haina salio au kiwango kilichobaki. Ongeza salio au ongeza kikomo chako katika akaunti yako nao, kisha jaribu tena.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s haikukubali ufunguo wako. Huenda umekosewa kuandikwa, umebatilishwa au umekwisha muda wake. Unda ufunguo mpya na ubandike hapa.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s imekataa ombi hili kwa ajili ya ufunguo wako. Ufunguo huenda hauna ufikiaji wa mtindo au kipengele hiki, au akaunti yako inahitaji uthibitishaji.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Mtindo "%1$s" haupatikani kutoka kwa %2$s kwa ufunguo wako. Chagua mtindo mwingine katika mipangilio ya AI.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Mpango wako wa %2$s haujumuishi modeli ya "%1$s". Chagua modeli nyingine katika mipangilio ya AI, au boresha mpango wako nao.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s inazuza kasi ya ufunguo wako kutuma maombi. Subiri dakika moja kisha ujaribu tena, au ongeza kiwango chako cha kikomo nao.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s inapata shida kwa sasa (kukatika kwa mtandao au mzigo mkubwa upande wao). Hakuna tatizo na mipangilio yako. Jaribu tena hivi karibuni.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Ombi la AI limeshindwa kwa sababu hatikuweza kuiteua. Jaribu tena; likiendelea kutokea, wasiliana na huduma kwa wateja ukiwa na maelezo yaliyo hapa chini.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Mtoa huduma wa AI amejibu kwa mfumo ambao programu-jalizi hii haikuweza kusoma. Jaribu tena; ikiwa itaendelea kutokea, chagua mtindo mwingine au wasiliana na huduma kwa wateja.','Custom (OpenAI-compatible)'=>'Maalum (Inayoendana na OpenAI)','Save a key for this provider first.'=>'Hifadhi ufunguo kwa mtoa huduma huyu kwanza.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Ufunguo wako unafanya kazi, lakini mtoa huduma hajaorodhesha mfano wa maandishi kwa ajili yake. Ongeza mfano mwenyewe hapa chini.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Imeunganishwa. %1$s amejibu kwa kutumia %2$s. Vipengele vyako vya AI viko tayari kutumika.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Wajibu wako wa mtumiaji hauruhusiwi kutumia AI kwenye tovuti hii. Uliza msimamizi.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Tovuti hii imefikia kikomo chake cha matumizi ya AI ya kila mwezi. Msimamizi anaweza kukiinua katika mipangilio ya AI.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Tovuti hii imefikia kikomo chake cha kila mwezi cha maombi ya AI. Msimamizi anaweza kukiongeza katika mipangilio ya AI.','Usage and cost'=>'Matumizi na gharama','The log, limits and role permissions apply to AI used through: %s.'=>'Kumbukumbu, vikomo na ruhusa za nafasi hutumika kwa AI inayotumiwa kupitia: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Gharama ni za makisio, zimehesabiwa kutoka kwa bei zilizochapishwa; mfano ambao hauna bei inayojulikana huhesabiwa kama sifuri.','This month: %1$s requests, about %2$s.'=>'Mwezi huu: maombi %1$s, takriban %2$s.','When'=>'Wakati','Who'=>'Nani','Used for'=>'Imetumika kwa','Model'=>'Mfano','Tokens in / out'=>'Ishara ndani / nje','About'=>'Kuhusu','Result'=>'Matokeo','No AI requests have been made yet.'=>'Hakuna maombi ya AI yaliyofanywa bado.','Done'=>'Imekamilika','Limits and permissions'=>'Mipaka na ruhusa','Monthly spending limit (US dollars)'=>'Kikomo cha matumizi ya kila mwezi (dola za US)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Acha wazi kukiwa hakuna kikomo. AI inasimama kwa mwezi uliosalia mara tu gharama inayokadiriwa inapofikia kiwango hicho.','Monthly request limit'=>'Kikomo cha maombi cha kila mwezi','Leave empty for no limit.'=>'Acha wazi bila kikomo.','Who may use AI'=>'Nani anayeweza kutumia AI','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Weka alama yoyote ili kuruhusu kila mtu anayeweza kutumia vipengele vya programu-jalizi kutumia AI. Wasimamizi wanaweza kuitumia kila wakati.','Save limits and permissions'=>'Hifadhi vigezo na ruhusa','Limits and permissions saved.'=>'Vikomo na ruhusa zimehifadhiwa.','Security error, please refresh the page and try again.'=>'Hitilafu ya usalama, tafadhali weka upya ukurasa na ujaribu tena.','Missing newsletter settings. Please contact the admin.'=>'Mipangilio ya jarida haipo. Tafadhali wasiliana na msimamizi.','Invalid newsletter settings. Please contact the admin.'=>'Mipangilio ya jarida si sahihi. Tafadhali wasiliana na msimamizi.','Invalid email address.'=>'Anwani ya barua pepe si sahihi.','Too many attempts. Please try again in a few minutes.'=>'Jaribio ni mengi mno. Tafadhali jaribu tena baada ya dakika chache.','Something went wrong. Please contact the admin.'=>'Kuna kitu kimeenda vibaya. Tafadhali wasiliana na msimamizi.','Map'=>'Ramani','Background video'=>'Video ya nyuma','%1$s: %2$d font files stored, stylesheet %3$s'=>'%1$s: faili za fonti %2$d zimehifadhiwa, laha ya mitindo %3$s','That family is not stored.'=>'Familia hiyo haijahifadhiwa.','Removed.'=>'Imeondolewa.','That is not a valid font family name.'=>'Hilo sio jina sahihi la familia ya fonti.','Google Fonts did not return that family. Check the name and try again.'=>'Google Fonts haikurudisha familia hiyo. Angalia jina na ujaribu tena.','The font files could not be downloaded or saved. Check that the uploads folder is writable.'=>'Faili za fonti hazikuweza kupakuliwa au kuhifadhiwa. Hakikisha kuwa folda ya kupakia inaweza kuandikika.','The font stylesheet could not be saved. Check that the uploads folder is writable.'=>'Faili la mtindo wa fonti halikuweza kuhifadhiwa. Hakikisha kuwa folda ya kupakia ina ruhusa ya kuandikwa.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Skripti za skrini ya msimamizi hazipo kwenye nakala hii ya programu-jalizi. Isakinishe upya kutoka kwenye kifurushi kilichotolewa.','This screen needs JavaScript.'=>'Skrini hii inahitaji JavaScript.','Languages'=>'Lugha','Upgrade'=>'Boresha','Pricing'=>'Bei','Start Trial'=>'Anza Jaribio','Account'=>'Akaunti','Contact Us'=>'Wasiliana Nasi','Affiliation'=>'Ushirika','the kind of softwarePlugin'=>'Programu-jalizi','greetingHey %s,'=>'Habari %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Jiandikishe kupata arifa za barua pepe kwa ajili ya usalama na masasisho ya vipengele, maudhui ya elimu, na matoleo ya mara kwa mara, na ili kushiriki maelezo ya msingi ya mazingira ya WordPress. Hii itatusaidia kufanya %s iendane zaidi na tovuti yako na iwe bora zaidi katika kufanya kile unachohitaji ifanye.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Jiandikishe ili upate arifa za barua pepe kuhusu usalama na masasisho ya vipengele, maudhui ya elimu, na matoleo ya mara kwa mara, na ili kushiriki maelezo fulani ya kimsingi ya mazingira ya WordPress.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Ukiacha hili, hakuna nchi iliyoharibika! %1$s itaendelea kufanya kazi vizuri tu.','Allow & Continue'=>'Ruhusu na Uendelee','verbSkip'=>'Ruka','Skipping, please wait'=>'Inaruka, tafadhali subiri','Continue'=>'Endelea','Please wait'=>'Tafadhali subiri','as activating pluginActivating'=>'Inafanya kazi','This will allow %s to'=>'Hii itaruhusu %s kuwezesha','Privacy Policy'=>'Sera ya Faragha','Terms of Service'=>'Masharti ya Huduma','License Agreement'=>'Mkataba wa Leseni','Have a license key?'=>'Una ufunguo wa leseni?','Activate License'=>'Washa Leseni','View Basic Profile Info'=>'Tazama Taarifa za Wasifu za Msingi','Your WordPress user\'s: first & last name, and email address'=>'Jina la kwanza na la mwisho, na anwani ya barua pepe ya mtumiaji wako wa WordPress','View Basic Website Info'=>'Onyesha Maelezo ya Msingi ya Tovuti','Homepage URL & title, WP & PHP versions, and site language'=>'URL na kichwa cha ukurasa wa nyumbani, matoleo ya WP na PHP, na lugha ya tovuti','View Basic %s Info'=>'Tazama Taarifa za Msingi za %s','Current %s & SDK versions, and if active or uninstalled'=>'Matoleo ya sasa ya %s & SDK, na ikiwa yanatumika au yameondolewa','Newsletter'=>'Jarida','Updates, announcements, marketing, no spam'=>'Sasisho, matangazo, masoko, hakuna taka data','View Diagnostic Info'=>'Tazama Taarifa za Utambuzi','WordPress & PHP versions, site language & title'=>'Toleo la WordPress na PHP, lugha na kichwa cha tovuti','View Plugins & Themes List'=>'Tazama Orodha ya Programu-jalizi na Mandhari','Names, slugs, versions, and if active or not'=>'Majida, slug, matoleo, na ikiwa ni amilifu au la','optional'=>'si lazima','Never miss an important update'=>'Usikose kamwe sasisho muhimu','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Tumeleta chaguo hili ili usipate kukosa sasisho muhimu na kutusaidia kufanya %s iendane vyema na tovuti yako na iwe bora zaidi katika kufanya kile unachohitaji ifanye.','Thank you for updating to %1$s v%2$s!'=>'Asante kwa kusasisha hadi %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Kiambishi awali lazima kiwe na herufi 1 hadi 8 ndogo au tarakimu, kianze na herufi, na kisiwe jina la programu-jalizi.','You are not allowed to edit this item.'=>'Huruhusiwi kuhariri kipengele hiki.','You are not allowed to do this.'=>'Huruhusu kufanya hivi.','Safe mode was turned off because it no longer matches your login. Reload the page.'=>'Hali salama imezimwa kwa sababu hailingani tena na kuingia kwako. Pakia upya ukurasa.','Only an administrator can use safe mode.'=>'Ni msimamizi pekee anayeweza kutumia hali salama.','Safe mode needs a normal browser login.'=>'Hali salama inahitaji kuingia kwenye kivinjari cha kawaida.','Safe mode could not be set up.'=>'Hali salama haikuweza kusanidiwa.','Safe mode needs write access to the wp-content/mu-plugins folder.'=>'Hali salama inahitaji idhini ya kuandika kwenye folda ya wp-content/mu-plugins.','Safe mode could not write to the wp-content/mu-plugins folder.'=>'Hali salama haikuweza kuandika kwenye folda ya wp-content/mu-plugins.','Sandwich Studio'=>'Sandwich Studio','That page does not exist, or it has been deleted.'=>'Ukurasa huo haupo, au umefutwa.','Sorry, you are not allowed to edit this item in Sandwich Studio.'=>'Samahani, huruhusiwi kuhariri kipengele hiki katika Sandwich Studio.','Sandwich Studio is not built. Reinstall the plugin.'=>'Sandwich Studio haijajengwa. Sakinisha tena programu-jalizi.','Add title'=>'Ongeza kichwa','Type / to choose a block'=>'Andika / ili kuchagua kizuizi','Loading Sandwich Studio…'=>'Inapakia Sandwich Studio…','Sandwich Studio needs JavaScript. Use the normal editor instead.'=>'Sandwich Studio inahitaji JavaScript. Tumia kihariri cha kawaida badala yake.','Edit “%s” with Sandwich Studio'=>'Hariri “%s” ukitumia Sandwich Studio','Edit with Sandwich Studio'=>'Hariri kwa Sandwich Studio','Blank canvas'=>'Turubai tupu','A migration step is running right now. Try again in a minute.'=>'Hatua ya kuhamisha data inaendelea sasa hivi. Jaribu tena baada ya dakika moja.','Thank you for subscribing!'=>'Asante kwa kusajili!','Something went wrong. Please contact the administrator.'=>'Kuna kitu kimeenda vibaya. Tafadhali wasiliana na msimamizi.','Years'=>'Miaka','Months'=>'Miezi','Weeks'=>'Wiki','Days'=>'Siku','Hours'=>'Masaa','Minutes'=>'Dakika','Seconds'=>'Sekunde','Go to slide %d'=>'Nenda kwenye slaidi %d','You\'re already subscribed to our newsletter'=>'Tayari umesajiliwa kupokea jarida letu','Email address is already subscribed.'=>'Anwani ya barua pepe tayari imesajiliwa.','MailPoet plugin not found. Please contact the admin.'=>'Program-in-soma ya MailPoet haipatikani. Tafadhali wasiliana na msimamizi.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Imetengenezwa na Neil Lock, Mkurugenzi Mtendaji wa Zinn Digital® Ltd','Version %s'=>'Toleo la %s','Page Builder Sandwich website'=>'Tovuti ya Page Builder Sandwich','Zinn Digital® website'=>'Tovuti ya Zinn Digital®','Settings saved.'=>'Mipangilio imehifadhiwa.','See the Pro plans and pricing'=>'Tazama mipango ya Pro na bei','Front-end output'=>'Matokeo ya mbele','Class name prefix'=>'Kiambishi awali cha jina la darasa','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Kila jina la darasa ambalo programu-jalizi huchapisha kwenye kurasa zako linaanza na kiambishi hiki, ili kurasa zisifunue ni programu-jalizi ipi iliyozijenga. Herufi ndogo 1 hadi 8 au tarakimu, zinazoanza na herufi moja.','Save'=>'Hifadhi','Beta updates'=>'Sasisho za Beta','This site receives beta versions as updates.'=>'Tovuti hii hupokea matoleo ya beta kama sasisho.','This site receives stable versions only.'=>'Tovuti hii inapokea matoleo thabiti pekee.','Change this on the Account page'=>'Badilisha hii kwenye ukurasa wa Akaunti','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Matoleo ya Beta hutolewa kwa usakinishaji wa Pro wenye leseni ambao umeunganishwa na akaunti yao. Mara baada ya kuunganishwa, unaweza kujiunga kupitia ukurasa wa Akaunti.','The request converting this post stopped before it finished, so the post was skipped. Open it to convert it, or convert it again from here.'=>'Ombi la kubadilisha chapisho hili lilisimama kabla halijakamilika, kwa hiyo chapisho lilirukwa. Lifungue ili ulibadilishe, au ulibadilishe tena kutoka hapa.','There is no backup of this post to restore.'=>'Hakuna nakala rudufu ya chapisho hili ya kurejesha.','The converted content could not be saved.'=>'Maudhui yaliyobadilishwa hayakuweza kuhifadhiwa.','Unknown error.'=>'Hitilafu isiyojulikana.','No legacy content has been checked yet.'=>'Hakuna maudhui ya zamani yaliyochunguzwa bado.','Restoring legacy content: %1$d of %2$d posts.'=>'Inarejesha maudhui ya zamani: machapisho %1$d kati ya %2$d.','Converting legacy content: %1$d of %2$d posts.'=>'Inabadilisha maudhui ya zamani: machapisho %1$d kati ya %2$d.','Undo finished: %1$d restored, %2$d failed.'=>'Tendua imekamilisha: %1$d zimerejeshwa, %2$d zimeshindwa.','Conversion finished: %1$d converted, %2$d unchanged, %3$d failed.'=>'Ubadilishaji umekamilika: %1$d imebadilishwa, %2$d haijabadilishwa, %3$d imeshindwa.','Legacy content'=>'Maudhui ya zamani','Pages made with earlier versions of Page Builder Sandwich are converted to blocks in the background. Every post is backed up first, so each conversion can be undone.'=>'Kurasa zilizoundwa kwa matoleo ya awali ya Page Builder Sandwich zinabadilishwa kuwa vizuizi kwa nyuma. Kila chapisho hifadhi rudufu yake inatengenezwa kwanza, kwa hivyo kila mabadiliko yanaweza kutenduliwa.','%d post still holds legacy content.'=>'Chapisho %d bado lina maudhui ya zamani.' . "\0" . 'Machapisho %d bado yana maudhui ya zamani.','%d post has a backup.'=>'Machapisho %d yana nakala rudufu.' . "\0" . 'Machapisho %d yana nakala rudufu.','%d post could not be handled'=>'Chapisho %d halikuweza kushughulikiwa' . "\0" . 'Machapisho %d hayakuweza kushughulikiwa','Post %d'=>'Chapisho %d','Conversion started. It continues in the background; you can leave this page.'=>'Ubadilishaji umeanza. Unaendelea chinichini; unaweza kuacha ukurasa huu.','Convert legacy content'=>'Badili maudhui ya zamani','Restore every converted post to its legacy content? Changes made to those posts since they were converted will be lost.'=>'Rejesha kila chapisho lililobadilishwa kuwa maudhui yake ya awali? Mabadiliko yaliyofanywa kwa machapisho hayo tangu yalipobadilishwa yatapotea.','Undo started. It continues in the background; you can leave this page.'=>'Tendeni limeanza. Linaendelea chinichini; unaweza kuacha ukurasa huu.','Undo all conversions'=>'Tendua mabadiliko yote','Shortcode tag'=>'Lebo ya msimbo mfupi','Use letters, numbers, dashes and underscores only.'=>'Tumia herufi, namba, vistari na mistari ya chini pekee.','Attribute name'=>'Jina la sifa','Add attribute'=>'Ongeza sifa','Content'=>'Maudhui','Shortcode'=>'Nambari fupi','Choose a shortcode tag in the block settings.'=>'Chagua lebo ya msimbo mfupi katika mipangilio ya kizuizi.','The "%s" control from the old editor is not available in the block editor. Enter the value as text.'=>'Udhibiti wa "%s" kutoka kwa kihariri cha zamani haupatikani katika kihariri cha vizuizi. Weka thamani kama maandishi.','Choose image'=>'Chagua picha','Choose file'=>'Chagua faili','— Default —'=>'— Chaguomsingi —','Advanced styling'=>'Mtindo wa kina','Inline CSS'=>'CSS ya Ndani','CSS declarations, for example: min-height: 380px; background-color: #333'=>'Matamshi ya CSS, kwa mfano: min-height: 380px; background-color: #333','Effects (legacy classes)'=>'Madhara (madarasa ya urithi)','Space-separated effect names carried over from older versions, for example: hover-shadow'=>'Majina ya athari yaliyotenganishwa na nafasi tupu yaliyohamishwa kutoka matoleo ya zamani, kwa mfano: hover-shadow','Row'=>'Safu','Width'=>'Upana','Content width'=>'Upana wa maudhui','Full width'=>'Upana kamili','Full width, content kept in the middle'=>'Upana wote, maudhui yamewekwa katikati','Link'=>'Unganisha','Link address'=>'Anwani ya kiungo','Open in a new tab'=>'Fungua katika kichupo kipya','Link relationship'=>'Uhusiano wa kiungo','Alignment'=>'Mpangilio','None'=>'Hakuna','Left'=>'Kushoto','Centre'=>'Kituo','Right'=>'Kulia','Button text'=>'Maandishi ya kitufe','Add text…'=>'Ongeza maandishi…','Icon'=>'Ikoni','SVG markup'=>'Alama ya SVG','Scripts, links and external references are removed before the icon is shown.'=>'Hati za mfumo, viungo na marejeleo ya nje huondolewa kabla ya aikoni kuonyeshwa.','Accessible label'=>'Lebo inayoweza kufikiwa','Leave empty for a decorative icon.'=>'Acha wazi kwa ajili ya ikoni ya urembo.','Paste SVG markup in the block settings.'=>'Bandika msimbo wa SVG katika mipangilio ya kizuizi.','New setting name'=>'Jina jipya la mpangilio','For example: title or text'=>'Kwa mfano: kichwa au maandishi','Add setting'=>'Ongeza mpangilio','Widget'=>'Wijeti','Choose a widget'=>'Chagua wijeti','Widget area'=>'Eneo la wijeti','Choose a widget area'=>'Chagua eneo la wijeti','This image has no width and height, so the page will jump when it loads. Choose it from the Media Library, or set its width and height.'=>'Picha hii haina upana wala urefu, kwa hiyo ukurasa utaruka wakati unapakiwa. Ichague kutoka kwenye Maktaba ya Medya, au uweke upana na urefu wake.','This video is not from the Media Library, so its size is unknown and the page will jump when it loads. Upload it to the Media Library instead.'=>'Video hii haitoki kwenye Maktaba ya Medya, kwa hiyo ukubwa wake haujulikani na ukurasa utaruka inapopakia. Ipakie kwenye Maktaba ya Medya badala yake.','An image, video or frame in this HTML has no width and height, so the page will jump when it loads. Add width and height attributes to it.'=>'Picha, video au fremu katika HTML hii haina upana na urefu, kwa hivyo kurasa itaruka inapopakia. Ongeza sifa za upana na urefu kwake.','This embed resizes itself after it loads, which moves the content below it. Give it room or place it lower on the page.'=>'Kibiriti hiki kinajirekebisha ukubwa baada ya kupakia, jambo ambalo linasogeza maudhui yaliyo chini yake. Ipe nafasi au iweke chini zaidi kwenye ukurasa.','Layout shift'=>'Kuhama kwa mpangilio','Heading'=>'Kichwa cha habari','Text'=>'Maandishi','Style'=>'Mtindo','Plain'=>'Wazi','Accent'=>'Lugha','No languages to switch between. The switcher appears when a translation plugin lists two or more languages.'=>'Hakuna lugha za kubadilisha kati yake. Kitufe cha kubadilisha huonekana wakati plagi ya utafsiri inaorodhesha lugha mbili au zaidi.','Switcher'=>'Kibadilishaji','Show the current language'=>'Onyesha lugha ya sasa','%s is also editing this page. Saving may overwrite their changes.'=>'%s pia anahariri ukurasa huu. Kuhifadhi kunaweza kubatilisha mabadiliko yao.','Block library'=>'Maktaba ya vizuizi','Layers'=>'Matabaka','Close panel'=>'Funga kidirisha','Page canvas'=>'Turubai ya ukurasa','Revisions'=>'Masahihisho','Block settings'=>'Mipangilio ya kuzuia','Add block: %s'=>'Ongeza kizuizi: %s','(no title)'=>'(hakuna kichwa)','Open in Studio: %s'=>'Fungua katika Studio: %s','Undo'=>'Tendua','Redo'=>'Rudia tena','Show or hide layers'=>'Onyesha au ficha tabaka','Show or hide the block library'=>'Onyesha au ficha maktaba ya bloku','Show revisions'=>'Onyesha masahihisho','Open the normal editor'=>'Fungua kihariri cha kawaida','Keyboard shortcuts'=>'Njia za mkato za kibodi','Preview: desktop'=>'Hakiki: eneo-kazi','Preview: tablet'=>'Onyesho la kukagua: kompyuta kibao','Preview: mobile'=>'Hakiki: simu ya mkononi','Copy style of the selected block'=>'Nakili mtindo wa kizuizi kilichochaguliwa','Paste style onto the selected block'=>'Bandika mtindo kwenye kizuizi kilichochaguliwa','Copy the selected section'=>'Nakili sehemu iliyochaguliwa','Paste a copied section'=>'Bandika sehemu iliyonakiliwa','Turn off safe mode'=>'Zima hali salama','Turn on safe mode (other plugins off, for you, in Studio only)'=>'Washa hali salama (programu jalizi nyingine zikiwa zimezimwa, kwako, katika Studio pekee)','Published'=>'Imechapishwa','Scheduled'=>'Imepangwa','Pending review'=>'Inasubiri ukaguzi','Private'=>'Binafsi','Draft'=>'Rasimu','All changes saved'=>'Mabadiliko yote yamehifadhiwa','Saving…'=>'Inahifadhi…','Autosaving…'=>'Inahifadhi kiotomatiki…','Unsaved changes'=>'Mabadiliko ambayo hayajahifadhiwa','autosaved'=>'imehifadhiwa kiotomatiki','Desktop preview'=>'Onyesho la kukagua la eneo-kazi','Tablet preview'=>'Hakikisho la kompyuta kibao','Mobile preview'=>'Hakiki ya simu ya mkononi','Studio toolbar'=>'Upau wa zana za Studio','Back to the normal editor'=>'Rudi kwenye kihariri cha kawaida','Page title'=>'Kichwa cha ukurasa','Preview width'=>'Upana wa hakikao','Command palette'=>'Palette ya amri','View page (opens in a new tab)'=>'Tazama ukurasa (inafunguka katika kichupo kipya)','Update'=>'Sasisha','Save draft'=>'Hifadhi rasimu','Publish'=>'Chapisha','Restore unsaved changes?'=>'Rejesha mabadiliko ambayo hayajahifadhiwa?','This page has changes that were never saved. They were kept in this browser:'=>'Ukurasa huu una mabadiliko ambayo hayajawahi kuhifadhiwa. Yamewekwa katika kivinjari hiki:','This page has a newer autosave than the saved version:'=>'Ukurasa huu una hifadhi otomatiki mpya zaidi kuliko toleo lililohifadhiwa:','Restore unsaved changes'=>'Rejesha mabadiliko ambayo hayajahifadhiwa','Discard'=>'Tupa','Revisions could not be loaded.'=>'Marekebisho hayakuweza kupakiwa.','Revision restored. Save to keep it, or undo to go back.'=>'Toleo limerejeshwa. Hifadhi ili uliweke, au batilisha ili urudi.','Close revisions'=>'Funga marekebisho','No revisions yet. Each save makes one.'=>'Hakuna marekebisho bado. Kila uhifadhi hufanya moja.','Revision from %s'=>'Toleo kutoka %s','Restore this revision'=>'Rejesha toleo hili','Cancel'=>'Ghairisha','Safe mode could not be changed.'=>'Hali salama haikuweza kubadilishwa.','Safe mode is on.'=>'Hali ya usalama imewashwa.','%d other plugin is switched off, for you and in Sandwich Studio only. The live site and other users are not affected.'=>'Moduli nyingine %d imezimwa, kwako na katika Sandwich Studio pekee. Tovuti ya moja kwa moja na watumiaji wengine hawajaathiriwa.' . "\0" . 'Programu jalizi zingine %d zimezimwa, kwako na katika Sandwich Studio pekee. Tovuti ya moja kwa moja na watumiaji wengine hawajaathiriwa.','Safe mode: switch other plugins off in Studio, for you only'=>'Hali salama: zima programu jalizi nyingine katika Studio, kwa ajili yako pekee','Safe mode'=>'Hali salama','Save your changes.'=>'Hifadhi mabadiliko yako.','Undo your last change.'=>'Tendua mabadiliko yako ya mwisho.','Redo your last undo.'=>'Rudisha kitendo chako cha mwisho cha kutendua.','Show or hide the layers panel.'=>'Onyesha au ficha paneli ya tabaka.','Display these keyboard shortcuts.'=>'Onyesha njia hizi za mkato za kibodi.','Select a block first.'=>'Chagua kizuizi kwanza.','Style copied. Paste it onto any block, on this site or another.'=>'Mtindo umenakiliwa. Ubandike kwenye kizuizi chochote, kwenye tovuti hii au nyingine.','The browser refused to copy.'=>'Kivinjari kimekataa kunakili.','Section copied. Paste it into any page, on this site or another.'=>'Sehemu imenakiliwa. Ibandike kwenye ukurasa wowote, kwenye tovuti hii au nyingine.','The clipboard does not hold a style copied from Sandwich Studio.'=>'Ubao wa kunakili hauna mtindo uliokopwa kutoka Sandwich Studio.','Style pasted onto %d block.'=>'Mtindo umewekwa kwenye kizuizi cha %d.' . "\0" . 'Mtindo umabandikwa kwenye vizuizi %d.','That style does not fit the selected block.'=>'Mtindo huo hautoshi kwenye kizuizi kilichochaguliwa.','The clipboard does not hold a copied section.'=>'Ubao klipu hauna sehemu iliyonakiliwa.','Section pasted.'=>'Sehemu imebandikwa.','Paste style'=>'Bandika mtindo','Paste section'=>'Bandika sehemu','Press Ctrl+V (or Cmd+V on a Mac) here to paste'=>'Bonyeza Ctrl+V (au Cmd+V kwenye Mac) hapa ili kubandika','Copy style'=>'Nakili mtindo','Copy section'=>'Nakili sehemu','Edit in Sandwich Studio'=>'Hariri katika Sandwich Studio','Saving failed. Check your connection and try again; your changes are kept in this browser.'=>'Imeshindwa kuhifadhi. Angalia mtandao wako kisha ujaribu tena; mabadiliko yako yamehifadhiwa kwenye kivinjari hiki.','Published.'=>'Imechapishwa.','Saved.'=>'Imehifadhiwa.','block titleButton link'=>'Kiungo cha kitufe','block descriptionA link styled as a button.'=>'Kiungo kilichopambwa kama kitufe.','block keywordbutton'=>'kitufe','block keywordlink'=>'kiungo','block keywordcall to action'=>'wito wa kuchukua hatua','block titleColumn'=>'Safu','block descriptionA column inside a row. It can hold any block.'=>'Safu ndani ya safu mlalo. Inaweza kuwa na kizuizi chochote.','block keywordcolumn'=>'safu wima','block keywordlayout'=>'mpangilio','block titleLanguage switcher (sample)'=>'Kibadilishaji cha lugha (mfano)','block descriptionLists the site\'s languages from the translation plugin, when one is active. It renders nothing otherwise.'=>'Inaorodhesha lugha za tovuti kutoka kwenye plagi-in ya utafsiri, wakati moja ikiwa amilifu. Haionyeshi chochote vinginevyo.','block keywordlanguage'=>'Lugha','block keywordswitcher'=>'kigeuzi','block titleSample content'=>'Maudhui ya mfano','block descriptionA heading and a paragraph, rendered with neutral class names. It is the reference block for the translation contract.'=>'Kichwa cha habari na aya, vilivyotolewa kwa majina ya darasa yasiyoegemea upande wowote. Nikiwa kizuizi cha marejeleo kwa ajili ya mkataba wa tafsiri.','block keywordsample'=>'mfano','block keywordtext'=>'maandishi','block titleIcon'=>'Ikoni','block descriptionAn SVG icon. The markup is cleaned before it is shown.'=>'Ikoni ya SVG. Alama zake husafishwa kabla ya kuonyeshwa.','block keywordicon'=>'aikoni','block keywordsvg'=>'svg','block titleRow'=>'Safu','block descriptionA row of columns. Stays readable if the plugin is ever turned off.'=>'Safu ya safu wima. Inaendelea kusomeka ikiwa programu-jalizi itazimwa wakati wowote.','block keywordrow'=>'safu','block keywordcolumns'=>'Safu','block titleShortcode (add-on)'=>'Nambari fupi (jalizo)','block descriptionA shortcode from an add-on written for the classic Page Builder Sandwich editor, with the settings the add-on declared.'=>'Shortcode kutoka kwa kiongezi kilichoandikwa kwa ajili ya kihariri cha kitamaduni cha Page Builder Sandwich, chenye mipangilio ambayo kiongezi hicho kilitangaza.','block keywordshortcode'=>'kodi fupi','block keywordadd-on'=>'nyongeza','block titleWidget area'=>'Eneo la wijeti','block descriptionShows the widgets in one of the theme\'s widget areas.'=>'Inaonyesha wijeti katika moja ya maeneo ya wijeti ya mada.','block keywordsidebar'=>'mwamba wa pembeni','block keywordwidget area'=>'eneo la wijeti','block titleWidget'=>'Wijeti','block descriptionShows one of the site\'s registered classic widgets.'=>'Inaonyesha mojawapo ya wijeti za asili zilizosajiliwa za tovuti.','block keywordwidget'=>'wijeti']];